<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#222}h1{text-align:center;font-size:20px;margin:5px}.center{text-align:center}.grid{width:100%;border-collapse:collapse;margin-top:15px}.grid th,.grid td{border:1px solid #aaa;padding:7px;text-align:left}.grid th{width:28%;background:#f1f1f1}.qr{float:right;width:110px}.photo{width:90px;height:105px;object-fit:cover;border:1px solid #aaa}.footer{margin-top:45px;display:flex;justify-content:space-between}</style></head><body><div class="center"><strong style="font-size:17px"><?= esc($school->name) ?></strong><h1>ADMISSION APPLICATION</h1><div><?= esc($application->application_no) ?></div></div><img class="qr" src="<?= $qr ?>"><table class="grid"><tr><th>Student name</th><td><?= esc($application->student_name) ?></td></tr><tr><th>Date of birth</th><td><?= esc($application->dob) ?></td></tr><tr><th>Gender</th><td><?= esc($application->gender) ?></td></tr><tr><th>Class / Shift</th><td><?= esc($application->class_name) ?><?= $application->shift_name?' / '.esc($application->shift_name):'' ?></td></tr><tr><th>Birth registration</th><td><?= esc($application->birth_registration_no) ?></td></tr><tr><th>Father</th><td><?= esc($application->father_name) ?> · <?= esc($application->father_mobile) ?></td></tr><tr><th>Mother</th><td><?= esc($application->mother_name) ?> · <?= esc($application->mother_mobile) ?></td></tr><tr><th>Guardian</th><td><?= esc($application->guardian_name) ?> · <?= esc($application->guardian_mobile) ?></td></tr><tr><th>Address</th><td><?= nl2br(esc($application->present_address)) ?></td></tr><tr><th>Submitted</th><td><?= esc($application->submitted_at) ?></td></tr><tr><th>Payment</th><td><?= esc(ucwords(str_replace('_',' ',$application->payment_status))) ?></td></tr></table><div class="footer"><span>Applicant signature</span><span>Guardian signature</span><span>Office use only</span></div></body></html>
